    B = R(:,1:34)\[R(:,35:end) Q'*M2(:,end-5:end)];
    M = [-A(:,end-85:end)+A(:,1:end-86)*B; -B];

    P1 = [121:185 p 115:120];
    P2 = [66,67,68,121,69,70,122,71,123,124,72,73,125,74,126,127,75,128,129,130,76,77,78,131,79,80,132,81,133,82,83,84,134,85,86,135,87,136,88,89,137,90,138,91,139,92,93,94,140,95,96,141,97,142,143,98,99,144,100,145,146,101,147,148,149,102,103,150,104,151,152,105,153,154,155,115,116,156,117,157,158,106,107,159,118,160,161,108,162,163,164,109,110,165,119,166,167,111,168,169,170,112,171,172,173,113,176,178,114,179,181,182,184,185,120,174,175,177,180,183];
    T = getT(M,P1(1:end-86),P1(end-85:end),P2);

